// ===========================================
// BUYER HEALTH SCORE ENGINE
// ===========================================

const buyers = $input.all().map(item => item.json);
const now = new Date();
const results = [];

for (const buyer of buyers) {
  let score = 100;
  const issues = [];
  const actions = [];

  // Skip inactive buyers - classify directly
  if (buyer.status === 'inactive') {
    results.push({
      ...buyer,
      health_score: 0,
      classification: 'Inactive',
      issues_detected: 'Buyer is inactive',
      suggested_actions: 'No action needed unless reactivation planned',
      alert_priority: 'none'
    });
    continue;
  }

  // --- Balance checks ---
  const balance = parseFloat(buyer.balance) || 0;
  if (balance <= 0) {
    score -= 30;
    issues.push('Zero or negative balance ($' + balance.toFixed(2) + ')');
    actions.push('Check billing and payment status');
  } else if (balance < 50) {
    score -= 15;
    issues.push('Low balance ($' + balance.toFixed(2) + ')');
    actions.push('Monitor balance and recharge status');
  }

  // --- Daily cap check ---
  const dailyCap = parseInt(buyer.daily_cap) || 0;
  const leadsToday = parseInt(buyer.leads_received_today) || 0;
  if (dailyCap > 0 && leadsToday >= dailyCap) {
    score -= 20;
    issues.push('Daily cap reached (' + leadsToday + '/' + dailyCap + ')');
    actions.push('Consider increasing daily cap if buyer wants more volume');
  }

  // --- Schedule check ---
  const schedStart = buyer.schedule_start || '00:00';
  const schedEnd = buyer.schedule_end || '23:59';
  const nowHour = now.getUTCHours();
  const nowMin = now.getUTCMinutes();
  const currentTime = nowHour * 60 + nowMin;
  const [startH, startM] = schedStart.split(':').map(Number);
  const [endH, endM] = schedEnd.split(':').map(Number);
  const startTime = startH * 60 + startM;
  const endTime = endH * 60 + endM;
  if (currentTime < startTime || currentTime > endTime) {
    score -= 10;
    issues.push('Outside active schedule (' + schedStart + '-' + schedEnd + ' ' + (buyer.timezone || 'EST') + ')');
    actions.push('Will resolve when schedule becomes active');
  }

  // --- Campaign check ---
  const campaignActive = String(buyer.campaign_active).toUpperCase() === 'TRUE';
  if (!campaignActive) {
    score -= 25;
    issues.push('Campaign is inactive');
    actions.push('Reactivate campaign or verify why it was paused');
  }

  // --- Ping tree check ---
  const pingTreeAssigned = String(buyer.ping_tree_assigned).toUpperCase() === 'TRUE';
  if (!pingTreeAssigned) {
    score -= 25;
    issues.push('No ping tree assigned');
    actions.push('Assign ping tree in Phonexa immediately');
  }

  // --- Zero leads today (while active) ---
  if (leadsToday === 0 && campaignActive && pingTreeAssigned && balance > 0) {
    score -= 20;
    issues.push('Active buyer with 0 leads received today');
    actions.push('Review Phonexa campaign filters and ping tree assignment');
  }

  // --- No leads in 48h+ ---
  const lastLeadAt = buyer.last_lead_received_at ? new Date(buyer.last_lead_received_at) : null;
  if (lastLeadAt) {
    const hoursSinceLastLead = (now - lastLeadAt) / (1000 * 60 * 60);
    if (hoursSinceLastLead > 48) {
      score -= 15;
      issues.push('No leads received in ' + Math.round(hoursSinceLastLead) + ' hours');
      actions.push('Investigate lead delivery pipeline for this buyer');
    }
  }

  // --- Complaints check ---
  const complaints = parseInt(buyer.complaint_count_last_7_days) || 0;
  if (complaints > 5) {
    score -= 15;
    issues.push(complaints + ' complaints in last 7 days');
    actions.push('Assign customer success follow-up urgently');
  } else if (complaints >= 3) {
    score -= 10;
    issues.push(complaints + ' complaints in last 7 days');
    actions.push('Monitor complaint trend and review lead quality');
  }

  // --- Rejected leads check ---
  const rejectedLeads = parseInt(buyer.rejected_leads_last_7_days) || 0;
  if (rejectedLeads > 10) {
    score -= 15;
    issues.push(rejectedLeads + ' rejected leads in last 7 days');
    actions.push('Review lead quality filters and buyer targeting criteria');
  }

  // --- Contactability check ---
  const contactability = parseFloat(buyer.contactability_rate) || 0;
  if (contactability < 30) {
    score -= 15;
    issues.push('Very low contactability rate (' + contactability + '%)');
    actions.push('Review lead freshness, buyer response time, and contact methods');
  } else if (contactability < 50) {
    score -= 10;
    issues.push('Below average contactability rate (' + contactability + '%)');
    actions.push('Analyze contactability trends and lead source quality');
  }

  // --- Cancellation risk check ---
  const cancellationRisk = (buyer.cancellation_risk || '').toLowerCase();
  if (cancellationRisk === 'high') {
    score -= 20;
    issues.push('High cancellation risk');
    actions.push('Escalate to account management for retention call');
  }

  // --- Auto-recharge issue ---
  const autoRecharge = String(buyer.auto_recharge_enabled).toUpperCase() === 'TRUE';
  const lastRechargeAt = buyer.last_recharge_at ? new Date(buyer.last_recharge_at) : null;
  if (autoRecharge && balance < 50) {
    const hoursSinceRecharge = lastRechargeAt ? (now - lastRechargeAt) / (1000 * 60 * 60) : 999;
    if (hoursSinceRecharge > 48) {
      score -= 15;
      issues.push('Auto-recharge enabled but no recharge in ' + Math.round(hoursSinceRecharge) + ' hours (balance: $' + balance.toFixed(2) + ')');
      actions.push('Check billing system and auto-recharge configuration');
    }
  }

  // --- Ensure minimum score of 0 ---
  score = Math.max(0, score);

  // --- Classification ---
  let classification;
  if (score >= 90) classification = 'Healthy';
  else if (score >= 70) classification = 'Warning';
  else if (score >= 50) classification = 'Needs Review';
  else classification = 'Critical';

  // --- Alert priority ---
  let alertPriority = 'none';
  if (classification === 'Critical') alertPriority = 'high';
  else if (classification === 'Warning') alertPriority = 'medium';
  else if (classification === 'Needs Review') alertPriority = 'low';

  results.push({
    ...buyer,
    health_score: score,
    classification,
    issues_detected: issues.join(' | ') || 'No issues detected',
    suggested_actions: actions.join(' | ') || 'No action needed',
    alert_priority: alertPriority
  });
}

return results.map(r => ({ json: r }));

// ===========================================
// FILTER & FORMAT SLACK ALERTS
// ===========================================

const buyers = $input.all().map(item => item.json);
const alerts = [];

for (const buyer of buyers) {
  if (buyer.classification === 'Healthy' || buyer.classification === 'Inactive') {
    continue;
  }

  let emoji, label, color;
  switch (buyer.classification) {
    case 'Critical':
      emoji = '🔴';
      label = 'CRITICAL';
      color = '#dc2626';
      break;
    case 'Warning':
      emoji = '🟡';
      label = 'WARNING';
      color = '#f59e0b';
      break;
    case 'Needs Review':
      emoji = '🔵';
      label = 'NEEDS REVIEW';
      color = '#3b82f6';
      break;
  }

  const issues = buyer.issues_detected.split(' | ');
  const actions = buyer.suggested_actions.split(' | ');

  const slackPayload = {
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: emoji + ' ' + label + ' - Buyer Monitoring Alert',
          emoji: true
        }
      },
      {
        type: 'section',
        fields: [
          {
            type: 'mrkdwn',
            text: '*Buyer:* ' + buyer.buyer_name + ' (ID: ' + buyer.buyer_id + ')'
          },
          {
            type: 'mrkdwn',
            text: '*Score:* ' + buyer.health_score + '/100'
          },
          {
            type: 'mrkdwn',
            text: '*Product:* ' + buyer.product
          },
          {
            type: 'mrkdwn',
            text: '*Priority:* ' + emoji + ' ' + (buyer.alert_priority || 'unknown').charAt(0).toUpperCase() + (buyer.alert_priority || 'unknown').slice(1)
          }
        ]
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: '*Issues Detected:*\n' + issues.map(i => '• ' + i).join('\n')
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: '*Suggested Actions:*\n' + actions.map(a => '• ' + a).join('\n')
        }
      },
      {
        type: 'context',
        elements: [
          {
            type: 'mrkdwn',
            text: 'Owner: Operations / Tech | Detected at: ' + new Date().toISOString()
          }
        ]
      },
      {
        type: 'divider'
      }
    ]
  };

  alerts.push({ json: { slackBody: JSON.stringify({ text: buyer.classification + ' Alert: ' + buyer.buyer_name, blocks: slackPayload.blocks }), _buyerName: buyer.buyer_name, _classification: buyer.classification } });
}

return alerts;

// ===========================================
// BUILD SUMMARY DATA + OPENAI PROMPT
// ===========================================

const allBuyers = $('Score Engine').all().map(item => item.json);
const now = new Date();

// --- Aggregate stats ---
const stats = {
  total: allBuyers.length,
  healthy: 0,
  warning: 0,
  critical: 0,
  needsReview: 0,
  inactive: 0
};

const urgentIssues = [];
let totalRevenueRisk = 0;

for (const buyer of allBuyers) {
  switch (buyer.classification) {
    case 'Healthy': stats.healthy++; break;
    case 'Warning': stats.warning++; break;
    case 'Critical': stats.critical++; break;
    case 'Needs Review': stats.needsReview++; break;
    case 'Inactive': stats.inactive++; break;
  }

  // Collect urgent issues (Critical first, then Warning)
  if (buyer.classification === 'Critical' || buyer.classification === 'Warning') {
    const dailySpend = (parseFloat(buyer.balance) || 0) > 0 ? 
      (parseInt(buyer.daily_cap) || 0) * 8 : 0; // Estimated $8 per lead avg

    if (buyer.classification === 'Critical') totalRevenueRisk += dailySpend;

    urgentIssues.push({
      buyerId: buyer.buyer_id,
      buyerName: buyer.buyer_name,
      score: buyer.health_score,
      classification: buyer.classification,
      issues: buyer.issues_detected,
      actions: buyer.suggested_actions,
      product: buyer.product,
      balance: buyer.balance,
      leadsToday: buyer.leads_received_today
    });
  }
}

// Sort urgent issues: Critical first, then by score ascending
urgentIssues.sort((a, b) => {
  if (a.classification === 'Critical' && b.classification !== 'Critical') return -1;
  if (a.classification !== 'Critical' && b.classification === 'Critical') return 1;
  return a.score - b.score;
});

const top5 = urgentIssues.slice(0, 5);

// --- Build OpenAI prompt ---
const prompt = `You are an operations analyst for Ecomfy Lead, a lead distribution company for insurance agents in the United States.

Generate a concise daily executive summary based on the following buyer monitoring data.

STATISTICS:
- Total buyers reviewed: ${stats.total}
- Healthy: ${stats.healthy}
- Warning: ${stats.warning}
- Critical: ${stats.critical}
- Needs Review: ${stats.needsReview}
- Inactive: ${stats.inactive}

TOP URGENT ISSUES:
${top5.map((issue, i) => `${i + 1}. Buyer ${issue.buyerId} (${issue.buyerName}) - Score: ${issue.score}/100 - ${issue.classification}\n   Product: ${issue.product} | Balance: $${issue.balance} | Leads today: ${issue.leadsToday}\n   Issues: ${issue.issues}\n   Suggested: ${issue.actions}`).join('\n\n')}

ESTIMATED DAILY REVENUE AT RISK: $${totalRevenueRisk.toLocaleString()}

Write the summary in this format:
1. Brief overview (2-3 sentences)
2. Top urgent items requiring immediate attention
3. Recommended actions for the operations team
4. Revenue risk assessment
5. Operational notes

Tone: professional, direct, actionable. Keep it under 300 words.`;

return [{
  json: {
    prompt,
    stats,
    top5,
    totalRevenueRisk,
    timestamp: now.toISOString()
  }
}];

// ===========================================
// FORMAT DAILY SUMMARY FOR SLACK
// ===========================================

const openaiResponse = $input.all()[0].json;
const summaryData = $('Build Summary').all()[0].json;
const stats = summaryData.stats;
const top5 = summaryData.top5;
const totalRevenueRisk = summaryData.totalRevenueRisk;

// Extract AI-generated text
let aiSummary = '';
try {
  aiSummary = openaiResponse.choices[0].message.content;
} catch (e) {
  aiSummary = 'AI summary unavailable. Please review the data manually.';
}

const slackPayload = {
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '📊 Daily Buyer Monitoring Summary',
        emoji: true
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*Date:* ' + new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) + ' | *Reviewed:* ' + stats.total + ' buyers'
      }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: '✅ *Healthy:* ' + stats.healthy },
        { type: 'mrkdwn', text: '🟡 *Warning:* ' + stats.warning },
        { type: 'mrkdwn', text: '🔴 *Critical:* ' + stats.critical },
        { type: 'mrkdwn', text: '⚪ *Inactive:* ' + stats.inactive },
        { type: 'mrkdwn', text: '🔵 *Needs Review:* ' + stats.needsReview },
        { type: 'mrkdwn', text: '💰 *Revenue Risk:* $' + totalRevenueRisk.toLocaleString() + '/day' }
      ]
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*⚠️ Top Urgent Issues:*\n' + top5.map((issue, i) => 
          (i + 1) + '. *' + issue.buyerName + '* (ID: ' + issue.buyerId + ') - Score: ' + issue.score + '/100 - ' + issue.classification + '\n    ' + issue.issues.split(' | ').slice(0, 2).join(', ')
        ).join('\n')
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*💡 AI Executive Summary:*\n' + aiSummary
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: '🤖 Generated by Buyer Monitoring System | ' + new Date().toISOString()
        }
      ]
    }
  ]
};

return [{ json: { slackBody: JSON.stringify({ text: "Daily Buyer Monitoring Summary", blocks: slackPayload.blocks }) } }];

// ===========================================
// PREPARE RESULTS FOR GOOGLE SHEETS
// ===========================================

const allBuyers = $('Score Engine').all().map(item => item.json);
const now = new Date().toISOString();

return allBuyers.map(buyer => ({
  json: {
    buyer_id: buyer.buyer_id,
    buyer_name: buyer.buyer_name,
    health_score: buyer.health_score,
    classification: buyer.classification,
    issues_detected: buyer.issues_detected,
    suggested_actions: buyer.suggested_actions,
    alert_sent: (buyer.classification !== 'Healthy' && buyer.classification !== 'Inactive') ? 'TRUE' : 'FALSE',
    evaluated_at: now
  }
}));

// ===========================================
// PREPARE LOG ENTRY
// ===========================================

const allBuyers = $('Score Engine').all().map(item => item.json);
const summaryData = $('Build Summary').all()[0].json;
const stats = summaryData.stats;
const now = new Date().toISOString();

// Count alerts sent
const alertsSent = allBuyers.filter(b => 
  b.classification !== 'Healthy' && b.classification !== 'Inactive'
).length;

return [{
  json: {
    run_id: 'run_' + Date.now(),
    timestamp: now,
    total_buyers: stats.total,
    critical_count: stats.critical,
    warning_count: stats.warning,
    healthy_count: stats.healthy,
    needs_review_count: stats.needsReview,
    inactive_count: stats.inactive,
    alerts_sent: alertsSent,
    summary_sent: 'TRUE',
    errors: 'None'
  }
}];
